def minimal_lexicographical_string(s):
    t = deque()
    u = []
    heap = []

    for char in s:
        heapq.heappush(heap, char)

    while heap or t:
        if heap and (not t or heap[0] <= t[-1]):
            u.append(heapq.heappop(heap))
        else:
            u.append(t.pop())

    return ''.join(u)

