def minimal_string(s):
    t = deque()
    u = []

    for char in s:
        if not t or char <= t[-1]:
            t.append(char)
        else:
            while t and char > t[-1]:
                u.append(t.pop())
            t.append(char)

    while t:
        u.append(t.pop())

    return ''.join(u[::-1])

